type ProfileCoverProps = {
    imageUrl?: string | null;
    focalPointX?: number;
    focalPointY?: number;
    zoom?: number;
    alt?: string;
    className?: string;
};

export function ProfileCover({
    imageUrl,
    focalPointX = 50,
    focalPointY = 50,
    zoom = 1,
    alt = "",
    className = "",
}: ProfileCoverProps) {
    return (
        <div className={`relative overflow-hidden bg-gradient-to-r from-amber-100 via-violet-100 to-blue-100 ${className}`}>
            {imageUrl && (
                // Presigned URLs are generated by the API, so native images avoid a Next host allow-list.
                // eslint-disable-next-line @next/next/no-img-element
                <img
                    src={imageUrl}
                    alt={alt}
                    draggable={false}
                    onDragStart={(event) => event.preventDefault()}
                    className="size-full select-none object-cover"
                    style={{
                        objectPosition: `${focalPointX}% ${focalPointY}%`,
                        transform: `scale(${zoom})`,
                        transformOrigin: `${focalPointX}% ${focalPointY}%`,
                    }}
                />
            )}
        </div>
    );
}
